"""缓存表的 DDL（唯一真相）：迁移、测试建临时表、脱机预览都从这里取语句。

与 `app/rag/schema.py` 同一套做法与同一组理由（迁移只跑一次、测试要跑很多次，
两处各写一份 DDL 必然漂移），所以这里只写**这一层特有的**取舍。

## 为什么语义缓存的向量落在 Postgres，而不是 Redis

`13.cache.md` §3 写的是「`redis`（缓存存储）+ `pgvector` 或 Redis 内相似度」——
两个选项都列了，本仓选 pgvector。理由按重要性排序：

1. **本机的 Redis 没有向量能力**（实测 7.4.11，`MODULE LIST` 返回空数组）——
   RediSearch / RedisJSON 都不在。选「Redis 内相似度」就得自己把向量拉回客户端算
   （等于把全量向量过一遍网络），或者换镜像（第 8 步的 redis checkpointer 已经
   因为这个原因在本机 `skip` 过一轮，见 `8.graph-runbook.md` §4.3）。
2. **pgvector 已经在跑**（第 10 步建的 `rag_chunks` 用的就是它，HNSW 索引现成）。
   同一套 `vector(n)` 维度口径、同一次迁移流程、同一个只读角色授权 —— 少一套机制。
3. **「候选 + 阈值」这件事需要一条能解释的查询**：`order by embedding <=> :q limit 5`
   能把最近邻与它的相似度一起返回（排障时「为什么没命中」要看的正是这个数）。
   客户端算相似度会把这件事变成一段谁都不知道对不对的 Python 代码。

代价是明确的：**缓存查询要走一次数据库连接**（约 1ms 级），而纯 Redis 是 0.2ms 级。
这条代价的补偿是 Redis 仍在链路上 —— 它承担「**完全同问**的快路径」与
「**embedding 缓存**」（见 `app/cache/backend.py`），所以最常见的那类重复问题
（用户刷新、同一句话被多次点开）根本不碰数据库。

## 两张表的分工

| 表 | 生命周期 | 谁维护 |
|---|---|---|
| `cache_corpus_versions` | **单行**，与知识库同龄 | `app/rag/ingest.py` 每次真正改动时 `+1` |
| `cache_semantic_entries` | 每行一条缓存答案，带 TTL 与 `is_active` | `app/cache/store.py` 的 `PostgresEntryStore` |

第三级失效（**版本失效**）就落在这张单行表上：`corpus_revision` 一变，
所有旧条目在 `freshness.check()` 里一次性失效 —— 不需要 `DELETE` 任何一行，
所以「失效」是**可解释且可回滚**的（`13.cache.md` §5 的「缓存失效三策略」第 3 条）。
"""

from __future__ import annotations

import re
from typing import Any

#: 语义缓存条目表（答案 + 出处 + 向量 + 版本指纹 + TTL）
ENTRIES_TABLE = "cache_semantic_entries"
#: 知识库版本表（单行；第三级失效的依据）
VERSIONS_TABLE = "cache_corpus_versions"

#: 本步建的两张表（导出成常量：`alembic/env.py` 要把它们排除在 autogenerate 之外）
CACHE_TABLES: tuple[str, ...] = (ENTRIES_TABLE, VERSIONS_TABLE)

#: 建表维度：**迁移与本模块必须一致**（`alembic/versions/*_add_cache_tables.py`）。
#: 它必须等于 `EMBEDDING_DIM` / `RAG_VECTOR_DIM` —— 三者一起改，改完重灌向量。
#: `tests/cache/test_cache_contracts.py` 会读迁移文件对账，漂移会红。
VECTOR_DIM = 1024

#: HNSW 参数与 `rag_chunks` 保持同一口径（理由见 `rag/schema.py` 的注释：
#: IVFFlat 要先有数据再建索引，而「先建索引、后灌数据」的流水线里它会退化）。
HNSW_M = 16
HNSW_EF_CONSTRUCTION = 64

_IDENTIFIER = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


def _check_identifier(name: str, value: str) -> None:
    """表名/函数名白名单校验（拼接前就地拦住），与 `rag/schema.py` 同一道闸。"""
    if not _IDENTIFIER.match(value):
        raise ValueError(f"表名只允许标识符字符，收到 {name}={value!r}")


def create_statements(
    vector_dim: int,
    *,
    entries_table: str = ENTRIES_TABLE,
    versions_table: str = VERSIONS_TABLE,
) -> list[str]:
    """建表 + 建索引，按依赖顺序返回（**幂等**：全部 IF NOT EXISTS）。

    `vector_dim <= 0` 时抛错：`vector(0)` 在 pgvector 里合法，
    于是「维度忘了配」会变成「库里全是零维向量」这种要读很久才发现的事故
    （与第 10 步同一口径，报错里写清该改哪几处）。
    """
    if vector_dim <= 0:
        raise ValueError(
            f"建缓存向量表需要明确的维度，收到 {vector_dim}。它必须与 EMBEDDING_DIM / "
            "RAG_VECTOR_DIM 一致（bge-m3 = 1024）。三处必须一起改："
            "① .env 的 EMBEDDING_DIM + RAG_VECTOR_DIM；② 迁移里的 vector(n)；③ 清空缓存表重灌。"
        )
    for name, value in (("entries_table", entries_table), ("versions_table", versions_table)):
        _check_identifier(name, value)

    return [
        "create extension if not exists vector",
        f"""
        create table if not exists {versions_table} (
            singleton        boolean     primary key default true,
            corpus_revision  bigint      not null default 1,
            bumped_at        timestamptz not null default now(),
            bumped_by        text        not null default 'init',
            constraint {versions_table}_singleton check (singleton)
        )
        """,
        # 初始化那一行：`on conflict do nothing` 让「表已存在但没数据」也能自愈
        # （人工清表、迁移中断、测试建表都会撞上这个状态）。
        f"insert into {versions_table} (singleton) values (true) on conflict do nothing",
        f"""
        create table if not exists {entries_table} (
            id             bigint generated by default as identity primary key,
            scope          text    not null,
            question       text    not null,
            question_hash  text    not null,
            embedding      vector({vector_dim}) not null,
            answer         text    not null,
            citations      jsonb   not null default '[]'::jsonb,
            meta           jsonb   not null default '{{}}'::jsonb,
            fingerprint    text    not null,
            corpus_revision bigint not null default 0,
            policy         text    not null default 'normal',
            ttl_seconds    integer not null,
            created_at     timestamptz not null default now(),
            expires_at     timestamptz not null,
            hit_count      integer not null default 0,
            last_hit_at    timestamptz,
            is_active      boolean not null default true
        )
        """,
        # 三条索引，各回答一个具体问题：
        #  ① HNSW：相似度查询走索引（`order by embedding <=> :q limit 5`）
        #  ② 唯一键：同一 scope + 同一版本指纹 + 同一句话只有一行（重复 set 走 upsert）
        #  ③ 附加索引：`purge` 与「按 scope 看缓存」不用扫全表
        f"""
        create index if not exists {entries_table}_embedding_hnsw
            on {entries_table} using hnsw (embedding vector_cosine_ops)
            with (m = {HNSW_M}, ef_construction = {HNSW_EF_CONSTRUCTION})
        """,
        f"""
        create unique index if not exists {entries_table}_identity
            on {entries_table} (scope, fingerprint, question_hash)
        """,
        f"""
        create index if not exists {entries_table}_active_scope
            on {entries_table} (scope, expires_at) where is_active
        """,
    ]


def drop_statements(
    *,
    entries_table: str = ENTRIES_TABLE,
    versions_table: str = VERSIONS_TABLE,
    drop_extension: bool = False,
) -> list[str]:
    """删表（**测试与本地重置用**；顺序：先条目表再版本表）。"""
    for name, value in (("entries_table", entries_table), ("versions_table", versions_table)):
        _check_identifier(name, value)
    statements = [
        f"drop table if exists {entries_table} cascade",
        f"drop table if exists {versions_table} cascade",
    ]
    if drop_extension:
        statements.append("drop extension if exists vector")
    return statements


def create_schema(
    connection: Any,
    vector_dim: int,
    *,
    entries_table: str = ENTRIES_TABLE,
    versions_table: str = VERSIONS_TABLE,
) -> list[str]:
    """在给定连接上建表（**幂等，不提交**）：迁移、测试建临时表都走它。"""
    statements = create_statements(
        vector_dim, entries_table=entries_table, versions_table=versions_table
    )
    for statement in statements:
        connection.exec_driver_sql(statement)
    return statements


def drop_cache_schema(
    connection: Any,
    *,
    entries_table: str = ENTRIES_TABLE,
    versions_table: str = VERSIONS_TABLE,
    drop_extension: bool = False,
) -> list[str]:
    """删表（**不提交**）。测试 teardown 与本地重置用它。"""
    statements = drop_statements(
        entries_table=entries_table, versions_table=versions_table, drop_extension=drop_extension
    )
    for statement in statements:
        connection.exec_driver_sql(statement)
    return statements


def table_exists(connection: Any, table: str = ENTRIES_TABLE) -> bool:
    """表是否存在（用 `to_regclass` 而不是 information_schema，与第 10 步同口径）。"""
    _check_identifier("table", table)
    row = connection.exec_driver_sql(f"select to_regclass('public.{table}') is not null").scalar()
    return bool(row)


def current_vector_dim(
    connection: Any, table: str = ENTRIES_TABLE, column: str = "embedding"
) -> int | None:
    """读出表上 `vector(n)` 的 n（维度对账的唯一手段）。

    为什么值得有这么一个函数：`vector(1024)` 与 `vector(768)` 在写库前都不报错，
    **维度恰好相同但向量空间不同**才是静默事故（缓存会开始返回不相干的答案，
    而它的相似度看起来完全正常）。所以至少要把「维度一致吗」变成一句能跑的自检。
    """
    for value in (table, column):
        _check_identifier("table/column", value)
    raw = connection.exec_driver_sql(
        "select atttypmod from pg_attribute "
        f"where attrelid = to_regclass('public.{table}') and attname = '{column}'"
    ).scalar()
    if raw is None:
        return None
    return int(raw) if int(raw) > 0 else None


__all__ = [
    "CACHE_TABLES",
    "ENTRIES_TABLE",
    "HNSW_EF_CONSTRUCTION",
    "HNSW_M",
    "VECTOR_DIM",
    "VERSIONS_TABLE",
    "create_schema",
    "create_statements",
    "current_vector_dim",
    "drop_cache_schema",
    "drop_statements",
    "table_exists",
]
